    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {                                         
        String username = txtUsername.getText().trim();
        String password = new String(txtPassword.getPassword()).trim();

        if (username.isEmpty() || password.isEmpty()) {
            JOptionPane.showMessageDialog(this, "Silakan masukkan username dan password!", "Peringatan", JOptionPane.WARNING_MESSAGE);
            return;
        }

        KasirService.UserInfo user = service.login(username, password);
        if (user == null) {
            JOptionPane.showMessageDialog(this, "Username atau password salah!", "Login Gagal", JOptionPane.ERROR_MESSAGE);
            return;
        }

        JOptionPane.showMessageDialog(this, "Selamat datang, " + user.nama + " (" + user.role + ")!", "Login Berhasil", JOptionPane.INFORMATION_MESSAGE);

        // Routing sesuai peran (Aturan Bisnis 10)
        switch (user.role.toLowerCase()) {
            case "kasir":
                if (service.getShiftAktif() != null && "OPEN".equalsIgnoreCase(service.getShiftAktif().getStatus())) {
                    new FormTransaksiKasir(user.nama).setVisible(true);
                } else {
                    new FormBukaShift(user.nama).setVisible(true);
                }
                break;
            case "admin_gudang":
                new FormKelolaBarang(user.nama).setVisible(true);
                break;
            case "pemilik":
                new FormLaporanPemilik(user.nama).setVisible(true);
                break;
            default:
                new FormTransaksiKasir(user.nama).setVisible(true);
                break;
        }
        this.dispose();
    }                                        

